const PREGUNTAS=[{"n": 1, "tema": "Permisos y documentación", "pregunta": "Con el permiso A2 se puede conducir una motocicleta de...", "opciones": ["35 kW de potencia y una relación potencia/peso no superior a 0,2 kW/kg.", "Cualquier potencia, si se limita electrónicamente.", "Hasta 50 kW si se lleva pasajero."], "correcta": 0, "explicacion": "El A2 autoriza motos de hasta 35 kW con una relación potencia/peso de 0,2 kW/kg como máximo, que no deriven de una moto de más de 70 kW.", "imagen": "img/naked_a2.jpg", "fallada": false}, {"n": 2, "tema": "Permisos y documentación", "pregunta": "Una moto de 90 kW de fábrica limitada a 35 kW...", "opciones": ["No se puede conducir con A2.", "Solo se puede conducir con A2 en vías urbanas.", "Se puede conducir con A2."], "correcta": 0, "explicacion": "Una moto limitada a 35 kW solo vale para A2 si su potencia de fábrica no supera el doble (70 kW). Con 90 kW de origen no se puede llevar con A2.", "imagen": "img/naked_a2.jpg", "fallada": true}, {"n": 3, "tema": "Normativa 2026", "pregunta": "Desde el 1 de octubre de 2026, los guantes de protección son obligatorios...", "opciones": ["Solo en autopistas y autovías.", "En todo tipo de vías.", "Solo en vías interurbanas."], "correcta": 2, "explicacion": "Desde el 1 de octubre de 2026 los guantes de protección son obligatorios solo en vías interurbanas. En ciudad no son obligatorios, aunque sí recomendables.", "imagen": "img/guantes.jpg", "fallada": true}, {"n": 4, "tema": "Normativa 2026", "pregunta": "El calzado cerrado que cubra todo el pie es obligatorio...", "opciones": ["Solo en vías interurbanas.", "Solo para el conductor.", "En todo tipo de vías, para conductor y pasajero."], "correcta": 2, "explicacion": "El calzado cerrado que cubra todo el pie es obligatorio en todo tipo de vías, ciudad incluida, y tanto para el conductor como para el pasajero.", "imagen": "img/botas.jpg", "fallada": true}, {"n": 5, "tema": "Normativa 2026", "pregunta": "¿Puede una motocicleta circular por el arcén en un atasco?", "opciones": ["Solo en tramos señalizados, con los carriles detenidos, en fila de uno y a 30 km/h como máximo.", "No, nunca.", "Sí, en cualquier atasco y a cualquier velocidad."], "correcta": 0, "explicacion": "No existe un permiso general: solo en tramos acordados y señalizados, con los carriles detenidos por congestión, en fila de uno y a 30 km/h como máximo.", "imagen": "img/P31.jpg", "fallada": true}, {"n": 6, "tema": "Normativa 2026", "pregunta": "El chaleco reflectante en una motocicleta...", "opciones": ["Solo es obligatorio para repartidores.", "Es opcional.", "Forma parte de su dotación y hay que ponérselo al bajar a la calzada o arcén de una vía interurbana."], "correcta": 2, "explicacion": "El chaleco forma parte de la dotación de la moto y el conductor debe ponérselo al bajarse y ocupar la calzada o el arcén de una vía interurbana.", "imagen": "img/chalecos.jpg", "fallada": false}, {"n": 7, "tema": "Normativa 2026", "pregunta": "Al adelantar a un ciclista fuera de poblado en una vía limitada a 90 km/h, la velocidad máxima durante el adelantamiento será...", "opciones": ["110 km/h.", "90 km/h.", "70 km/h."], "correcta": 2, "explicacion": "Fuera de poblado, al adelantar a un ciclista hay que ir al menos 20 km/h por debajo del límite de la vía: en una de 90 km/h, como máximo a 70 km/h.", "imagen": "img/P22.jpg", "fallada": true}, {"n": 8, "tema": "Frenada", "pregunta": "En una frenada en recta con firme seco, ¿qué freno aporta más capacidad de frenado?", "opciones": ["El trasero.", "Ambos por igual.", "El delantero."], "correcta": 2, "explicacion": "Al frenar, el peso se transfiere a la rueda delantera, por eso el freno delantero aporta la mayor parte de la frenada (en torno al 70 % en seco).", "imagen": "img/frenos.jpg", "fallada": false}, {"n": 9, "tema": "Frenada", "pregunta": "Si al frenar se bloquea la rueda delantera, debe...", "opciones": ["Accionar a fondo el freno trasero.", "Mantener el freno accionado.", "Soltar el freno delantero y volver a frenar de forma progresiva."], "correcta": 2, "explicacion": "Con la rueda delantera bloqueada se pierde la dirección. Hay que soltar el freno de inmediato y volver a frenar con más suavidad.", "imagen": "img/frenos.jpg", "fallada": true}, {"n": 10, "tema": "Frenada", "pregunta": "Si se bloquea la rueda trasera y la moto empieza a cruzarse...", "opciones": ["Soltar el freno de golpe.", "Mantener la moto recta y aflojar el freno de forma progresiva.", "Frenar más con el delantero."], "correcta": 1, "explicacion": "Si sueltas el freno de golpe con la moto cruzada, la rueda recupera agarre bruscamente y puede lanzarte. Mantén la moto recta y afloja progresivamente.", "imagen": "img/frenos.jpg", "fallada": true}, {"n": 11, "tema": "Frenada", "pregunta": "Con ABS, en una frenada de emergencia, debe...", "opciones": ["Bombear el freno.", "Usar solo el trasero.", "Frenar a fondo con ambos frenos y mantener la presión aunque note vibraciones."], "correcta": 2, "explicacion": "El ABS impide el bloqueo: puedes frenar a fondo con los dos frenos. La vibración en maneta y pedal es normal; no hay que soltar ni bombear.", "imagen": "img/frenos.jpg", "fallada": false}, {"n": 12, "tema": "Frenada", "pregunta": "Si es necesario frenar dentro de una curva, es preferible...", "opciones": ["Reducir dos marchas de golpe.", "Usar con fuerza el freno delantero.", "Frenar con suavidad, preferentemente con el trasero, o enderezar y frenar."], "correcta": 2, "explicacion": "El freno delantero en inclinación levanta la moto y abre la trayectoria. Si hay que frenar en curva, suave y preferentemente con el trasero, o enderezar y frenar.", "imagen": "img/curva.jpg", "fallada": true}, {"n": 13, "tema": "Curvas", "pregunta": "La trazada correcta en una curva es...", "opciones": ["Interior, exterior, interior.", "Exterior, interior, exterior, sin salir del carril.", "Por el centro del carril todo el tiempo."], "correcta": 1, "explicacion": "La trazada segura es exterior-interior-exterior dentro de tu carril: entras por fuera para ver la curva, buscas el vértice interior y sales abriendo.", "imagen": "img/P13a.jpg", "fallada": true}, {"n": 14, "tema": "Curvas", "pregunta": "Para iniciar un giro a la izquierda a 60 km/h mediante contramanillar...", "opciones": ["Se presiona el manillar hacia la derecha (empujando el puño izquierdo).", "Se frena con el trasero.", "Se gira el manillar hacia la izquierda."], "correcta": 0, "explicacion": "Por encima de unos 30 km/h se gira con contramanillar: para ir a la izquierda se empuja el puño izquierdo, es decir, el manillar se presiona ligeramente hacia la derecha.", "imagen": "img/inclinacion.jpg", "fallada": true}, {"n": 15, "tema": "Curvas", "pregunta": "En curvas lentas y cerradas o maniobras, la técnica adecuada es...", "opciones": ["Acompañar.", "El contrapeso.", "Descolgarse."], "correcta": 1, "explicacion": "En giros lentos y cerrados se usa el contrapeso: cuerpo erguido o hacia fuera y la moto más inclinada. Descolgarse es para curvas rápidas.", "imagen": "img/P14a.jpg", "fallada": false}, {"n": 16, "tema": "Curvas", "pregunta": "Si se produce flaneo (shimmy) en el manillar...", "opciones": ["Frenar bruscamente.", "Acelerar para estabilizar.", "Sujetar firme sin rigidez y reducir la velocidad gradualmente cerrando gas."], "correcta": 2, "explicacion": "Frenar o acelerar bruscamente agrava el flaneo. Sujeta el manillar firme pero sin rigidez y reduce la velocidad cerrando gas poco a poco.", "imagen": "img/mandos.jpg", "fallada": true}, {"n": 17, "tema": "La motocicleta", "pregunta": "La profundidad mínima del dibujo de los neumáticos de una motocicleta es...", "opciones": ["1,6 mm.", "2 mm.", "1 mm."], "correcta": 0, "explicacion": "La profundidad mínima legal del dibujo en motocicletas es de 1,6 mm. En ciclomotores es de 1 mm.", "imagen": "img/neumaticos.jpg", "fallada": false}, {"n": 18, "tema": "La motocicleta", "pregunta": "La presión de los neumáticos debe comprobarse...", "opciones": ["Solo en la ITV.", "En frío.", "Después de un trayecto largo."], "correcta": 1, "explicacion": "La presión se mide con los neumáticos fríos. En caliente el aire se dilata y la lectura sale más alta de lo real.", "imagen": "img/neumatico_taller.jpg", "fallada": false}, {"n": 19, "tema": "Pasajero y carga", "pregunta": "Con carácter general, ¿desde qué edad puede viajar un pasajero en moto?", "opciones": ["Desde los 7 años.", "Desde los 12 años.", "Desde los 16 años."], "correcta": 1, "explicacion": "Con carácter general el pasajero debe tener más de 12 años. Solo excepcionalmente más de 7 si conduce el padre, la madre, el tutor o un adulto autorizado.", "imagen": "img/pasajero.jpg", "fallada": true}, {"n": 20, "tema": "Pasajero y carga", "pregunta": "En curva, el pasajero debe...", "opciones": ["Acompañar la inclinación de la moto.", "Mantenerse vertical.", "Inclinarse hacia el lado contrario."], "correcta": 0, "explicacion": "El pasajero debe acompañar la inclinación de la moto. Si se inclina al contrario o se queda vertical, desequilibra la moto y altera la trayectoria.", "imagen": "img/pasajero.jpg", "fallada": false}, {"n": 21, "tema": "Pasajero y carga", "pregunta": "La carga en una motocicleta debe ir...", "opciones": ["Toda en el lado derecho.", "Lo más alta posible.", "Baja, centrada y repartida."], "correcta": 2, "explicacion": "La carga debe ir baja, centrada y repartida a ambos lados para no subir el centro de gravedad ni desequilibrar la moto.", "imagen": "img/maletas.jpg", "fallada": false}, {"n": 22, "tema": "Condiciones adversas", "pregunta": "Al comenzar a llover tras un periodo seco...", "opciones": ["El firme gana adherencia.", "El firme se vuelve especialmente deslizante.", "No cambia nada."], "correcta": 1, "explicacion": "Las primeras gotas mezclan el agua con polvo, aceite y restos de caucho y forman una película muy resbaladiza. Es el momento más peligroso.", "imagen": "img/P19.jpg", "fallada": false}, {"n": 23, "tema": "Condiciones adversas", "pregunta": "Al atravesar una zona de gravilla debe...", "opciones": ["Mantener la moto recta, sin frenar ni acelerar bruscamente.", "Inclinar la moto.", "Frenar con fuerza."], "correcta": 0, "explicacion": "Sobre gravilla hay muy poca adherencia: atraviesa con la moto recta y el gas constante, sin frenar, acelerar ni girar bruscamente.", "imagen": "img/P28.jpg", "fallada": false}, {"n": 24, "tema": "Condiciones adversas", "pregunta": "Las ráfagas de viento lateral son más probables...", "opciones": ["En ciudad.", "En el interior de los túneles.", "A la salida de túneles y en puentes."], "correcta": 2, "explicacion": "Al salir de un túnel o en puentes y viaductos desaparece la protección y el viento lateral golpea de repente.", "imagen": "img/P29.jpg", "fallada": false}, {"n": 25, "tema": "Condiciones adversas", "pregunta": "Las motocicletas deben circular de día...", "opciones": ["Sin luces.", "Con la luz de cruce encendida.", "Con la luz de carretera."], "correcta": 1, "explicacion": "Las motos deben circular siempre con la luz de cruce encendida, también de día, para ser más visibles.", "imagen": "img/R413.jpg", "fallada": true}, {"n": 26, "tema": "Conducción preventiva", "pregunta": "En circulación en grupo, en tramos rectos, la formación recomendada es...", "opciones": ["En zigzag (tresbolillo).", "Muy juntos para no separarse.", "En paralelo."], "correcta": 0, "explicacion": "En rectas, el zigzag o tresbolillo da a cada moto espacio y visibilidad. En paralelo dentro del carril no hay margen de maniobra.", "imagen": "img/grupo.jpg", "fallada": false}, {"n": 27, "tema": "Accidentes", "pregunta": "Ante un motorista accidentado consciente que lleva casco...", "opciones": ["Lo sentaremos en el arcén.", "Le quitaremos el casco para que respire mejor.", "No le quitaremos el casco; podemos abrir la visera y tranquilizarlo."], "correcta": 2, "explicacion": "Nunca se quita el casco a un motorista herido como norma general: puede agravar una lesión cervical. Se puede abrir la visera y tranquilizarlo.", "imagen": "img/casco_integral.jpg", "fallada": true}, {"n": 28, "tema": "Factor humano", "pregunta": "El efecto del alcohol se elimina...", "opciones": ["Tomando café.", "Haciendo ejercicio.", "Solo con el paso del tiempo."], "correcta": 2, "explicacion": "Solo el tiempo elimina el alcohol del organismo. Café, duchas o ejercicio no reducen la tasa.", "imagen": "img/etilometro.jpg", "fallada": false}, {"n": 29, "tema": "Normativa 2026", "pregunta": "Un intercomunicador integrado en el casco, certificado u homologado...", "opciones": ["Está permitido para comunicación o navegación si no afecta a la seguridad.", "Solo se permite en ciudad.", "Está prohibido."], "correcta": 0, "explicacion": "Desde la reforma de 2026 se permiten los dispositivos certificados u homologados integrados en el casco, solo para comunicación o navegación.", "imagen": "img/casco.jpg", "fallada": false}, {"n": 30, "tema": "Pasajero y carga", "pregunta": "Para una moto con remolque, las velocidades máximas genéricas...", "opciones": ["Se reducen un 50 %.", "Se reducen un 10 %.", "Son las mismas."], "correcta": 1, "explicacion": "Una moto con remolque tiene sus velocidades máximas genéricas reducidas en un 10 %.", "imagen": "img/maletas.jpg", "fallada": false}, {"n": 31, "tema": "Permisos y documentación", "pregunta": "¿Pueden circular los ciclomotores por autovía?", "opciones": ["Sí, por el arcén.", "No.", "Sí, a 45 km/h."], "correcta": 1, "explicacion": "Los ciclomotores tienen prohibido circular por autopistas y autovías. Las motocicletas sí pueden.", "imagen": "img/R105.jpg", "fallada": false}, {"n": 32, "tema": "Permisos y documentación", "pregunta": "Con el permiso B de más de 3 años, en España se puede conducir...", "opciones": ["Cualquier moto del A2.", "Solo ciclomotores.", "Una moto de 125 cm³ y 11 kW."], "correcta": 2, "explicacion": "El permiso B con más de 3 años autoriza a conducir en España motos del A1: hasta 125 cm³ y 11 kW. No sirve para motos del A2.", "imagen": "img/moto125.jpg", "fallada": true}, {"n": 33, "tema": "Permisos y documentación", "pregunta": "La velocidad máxima de una motocicleta en carretera convencional es...", "opciones": ["80 km/h.", "100 km/h.", "90 km/h."], "correcta": 2, "explicacion": "La velocidad máxima genérica de una moto en carretera convencional es de 90 km/h.", "imagen": "img/R301_90.jpg", "fallada": false}, {"n": 34, "tema": "Permisos y documentación", "pregunta": "En una vía urbana con un único carril por sentido, la velocidad máxima genérica es...", "opciones": ["50 km/h.", "30 km/h.", "20 km/h."], "correcta": 1, "explicacion": "En vías urbanas con un único carril por sentido, el límite genérico es 30 km/h. Con dos o más carriles por sentido es 50 km/h.", "imagen": "img/S28.jpg", "fallada": true}, {"n": 35, "tema": "Permisos y documentación", "pregunta": "La primera ITV de una motocicleta se pasa...", "opciones": ["A los 4 años.", "A los 5 años.", "A los 2 años."], "correcta": 0, "explicacion": "La primera ITV de una motocicleta es a los 4 años de su matriculación; después, cada 2 años.", "imagen": "img/elevador.jpg", "fallada": false}, {"n": 36, "tema": "La motocicleta", "pregunta": "El líquido de frenos debe cambiarse periódicamente porque...", "opciones": ["Se congela en verano.", "Se evapora.", "Absorbe humedad y pierde eficacia."], "correcta": 2, "explicacion": "El líquido de frenos es higroscópico: absorbe humedad, baja su punto de ebullición y pierde eficacia. Se cambia aproximadamente cada 2 años.", "imagen": "img/frenos.jpg", "fallada": false}, {"n": 37, "tema": "La motocicleta", "pregunta": "Un tacto esponjoso en la maneta de freno puede indicar...", "opciones": ["Aire en el circuito o líquido degradado.", "Neumático con poca presión.", "Cadena floja."], "correcta": 0, "explicacion": "Una maneta esponjosa suele indicar aire en el circuito o líquido degradado. Hay que revisarlo cuanto antes.", "imagen": "img/mandos.jpg", "fallada": false}, {"n": 38, "tema": "La motocicleta", "pregunta": "El neumático 120/70 ZR17: el número 17 indica...", "opciones": ["El diámetro de la llanta en pulgadas.", "El índice de carga.", "La anchura."], "correcta": 0, "explicacion": "En 120/70 ZR17, 120 es la anchura en mm, 70 el perfil en %, Z y R el código de velocidad y la estructura radial, y 17 el diámetro de la llanta en pulgadas.", "imagen": "img/neumaticos.jpg", "fallada": false}, {"n": 39, "tema": "Equipamiento", "pregunta": "Un casco que ha sufrido un golpe fuerte sin daños visibles...", "opciones": ["Solo hay que cambiar la visera.", "Puede seguir usándose.", "Debe sustituirse."], "correcta": 2, "explicacion": "Tras un golpe fuerte, el interior de poliestireno puede haberse aplastado aunque por fuera no se vea nada: ya no absorbería otro impacto. Hay que cambiarlo.", "imagen": "img/casco_integral.jpg", "fallada": false}, {"n": 40, "tema": "Equipamiento", "pregunta": "El casco modular puede usarse con la mentonera abierta...", "opciones": ["Siempre.", "Solo si está homologado como P/J.", "Nunca en ningún caso."], "correcta": 1, "explicacion": "Un casco modular solo puede usarse abierto si está homologado también como jet, con la marca P/J en la etiqueta.", "imagen": "img/casco.jpg", "fallada": true}, {"n": 41, "tema": "Equipamiento", "pregunta": "Las protecciones de nivel 2 respecto a las de nivel 1...", "opciones": ["Son menos seguras.", "Son iguales.", "Absorben más energía."], "correcta": 2, "explicacion": "Las protecciones de nivel 2 absorben más energía del impacto que las de nivel 1.", "imagen": "img/chaqueta.jpg", "fallada": false}, {"n": 42, "tema": "Equipamiento", "pregunta": "¿Qué elemento forma parte de la seguridad pasiva?", "opciones": ["Los frenos.", "El ABS.", "El casco."], "correcta": 2, "explicacion": "La seguridad pasiva reduce las consecuencias de un accidente, como el casco. El ABS y los frenos son seguridad activa: ayudan a evitarlo.", "imagen": "img/casco.jpg", "fallada": true}, {"n": 43, "tema": "Frenada", "pregunta": "Salir en una pendiente ascendente: la moto se sujeta con...", "opciones": ["El freno delantero y el pie derecho en el suelo.", "El freno trasero con el pie derecho y el pie izquierdo en el suelo.", "El embrague solo."], "correcta": 1, "explicacion": "En una salida en cuesta se sujeta la moto con el freno trasero (pie derecho) mientras el pie izquierdo apoya en el suelo, y se suelta al encontrar el punto de embrague.", "imagen": "img/P15.jpg", "fallada": false}, {"n": 44, "tema": "Curvas", "pregunta": "Unos brazos rígidos sobre el manillar...", "opciones": ["Transmiten las irregularidades y favorecen el flaneo.", "No influyen.", "Mejoran la estabilidad."], "correcta": 0, "explicacion": "Unos brazos rígidos transmiten las irregularidades del firme al manillar y favorecen oscilaciones como el flaneo. Deben ir ligeramente flexionados.", "imagen": "img/postura.jpg", "fallada": false}, {"n": 45, "tema": "Curvas", "pregunta": "La mirada en una curva debe dirigirse...", "opciones": ["Al borde de la calzada.", "A la rueda delantera.", "A la salida de la curva."], "correcta": 2, "explicacion": "La moto va hacia donde miras: la mirada debe ir a la salida de la curva, no al suelo ni al obstáculo.", "imagen": "img/curva.jpg", "fallada": true}, {"n": 46, "tema": "La motocicleta", "pregunta": "Con pasajero, la presión de los neumáticos...", "opciones": ["Se reduce.", "Se aumenta según el fabricante.", "No se modifica."], "correcta": 1, "explicacion": "Con pasajero o carga se aumenta la presión de los neumáticos siguiendo las indicaciones del fabricante.", "imagen": "img/neumatico_taller.jpg", "fallada": true}, {"n": 47, "tema": "Pasajero y carga", "pregunta": "La masa de un remolque arrastrado por una moto no puede superar...", "opciones": ["El 100 % de la masa de la moto.", "150 kg en cualquier caso.", "El 50 % de la masa en vacío de la moto."], "correcta": 2, "explicacion": "La masa del remolque no puede superar el 50 % de la masa en vacío de la moto.", "imagen": "img/maletas.jpg", "fallada": false}, {"n": 48, "tema": "Conducción preventiva", "pregunta": "Al ser adelantado por otro vehículo, el motorista debe...", "opciones": ["Frenar bruscamente.", "Acelerar.", "Mantener su trayectoria y no aumentar la velocidad."], "correcta": 2, "explicacion": "Al ser adelantado hay que mantener la trayectoria, no acelerar y, si es seguro, apartarse un poco a la derecha.", "imagen": "img/ruta.jpg", "fallada": false}, {"n": 49, "tema": "Señales", "pregunta": "En una glorieta tienen prioridad, salvo señalización...", "opciones": ["Los que van a entrar.", "Los que ya circulan por ella.", "Los que vienen por la derecha."], "correcta": 1, "explicacion": "Salvo señalización en contra, en una glorieta tienen prioridad los vehículos que ya circulan por ella.", "imagen": "img/P4.jpg", "fallada": false}, {"n": 50, "tema": "Señales", "pregunta": "En una señal de STOP sin vehículos a la vista...", "opciones": ["Hay que detenerse siempre.", "Basta con reducir la velocidad.", "No es necesario detenerse."], "correcta": 0, "explicacion": "En un STOP hay que detenerse siempre, aunque no venga nadie, en la línea de detención o antes de entrar en la intersección.", "imagen": "img/R2.jpg", "fallada": true}, {"n": 51, "tema": "Señales", "pregunta": "Un agente con el brazo levantado verticalmente indica...", "opciones": ["Reducir la velocidad.", "Detención para todos los que se acercan.", "Que se puede pasar."], "correcta": 1, "explicacion": "Un agente con el brazo levantado verticalmente ordena detenerse a todos los que se acercan, salvo a quien ya esté dentro de la intersección.", "imagen": "img/R100.jpg", "fallada": true}, {"n": 52, "tema": "Señales", "pregunta": "Brazo izquierdo extendido horizontalmente significa...", "opciones": ["Giro a la derecha.", "Giro a la izquierda.", "Voy a detenerme."], "correcta": 1, "explicacion": "El brazo izquierdo extendido horizontalmente indica que vas a girar o desplazarte a la izquierda.", "imagen": "img/R400a.jpg", "fallada": false}, {"n": 53, "tema": "Señales", "pregunta": "La luz antiniebla trasera se usa...", "opciones": ["Solo con condiciones de visibilidad muy desfavorables.", "Al circular en grupo.", "Siempre de noche."], "correcta": 0, "explicacion": "La antiniebla trasera solo se usa con condiciones meteorológicas o ambientales muy desfavorables, porque deslumbra a quien viene detrás.", "imagen": "img/P33.jpg", "fallada": false}, {"n": 54, "tema": "Factor humano", "pregunta": "El café o una ducha fría...", "opciones": ["Reducen la tasa a la mitad.", "Eliminan el alcohol.", "No eliminan el alcohol."], "correcta": 2, "explicacion": "Ni el café ni una ducha fría eliminan el alcohol. Solo despejan la sensación, pero la tasa sigue igual.", "imagen": "img/etilometro.jpg", "fallada": false}, {"n": 55, "tema": "Medio ambiente y puntos", "pregunta": "Usar el móvil sujetándolo con la mano supone la pérdida de...", "opciones": ["2 puntos.", "4 puntos.", "6 puntos."], "correcta": 2, "explicacion": "Usar el móvil sujetándolo con la mano mientras se conduce supone la pérdida de 6 puntos.", "imagen": "img/postura.jpg", "fallada": false}, {"n": 56, "tema": "Normativa 2026", "pregunta": "No llevar guantes en vía interurbana se sanciona con...", "opciones": ["200 € sin pérdida de puntos.", "100 € y 2 puntos.", "200 € y 4 puntos."], "correcta": 0, "explicacion": "No llevar guantes en vía interurbana es una infracción grave de 200 €, pero la DGT ha establecido que no supone pérdida de puntos.", "imagen": "img/guantes_nudillos.jpg", "fallada": true}, {"n": 57, "tema": "Normativa 2026", "pregunta": "Para despejar la vía aérea de un motorista que no respira, el casco lo retira...", "opciones": ["Nadie, nunca, aunque no respire.", "Cualquier persona, rápidamente.", "Una persona formada, entre dos y manteniendo alineados cabeza, cuello y tronco."], "correcta": 2, "explicacion": "Solo una persona formada, si el herido no respira, retira el casco entre dos personas y manteniendo alineados cabeza, cuello y tronco.", "imagen": "img/casco_integral.jpg", "fallada": true}, {"n": 58, "tema": "Normativa 2026", "pregunta": "En autopista con tráfico detenido y dos carriles, el corredor de emergencia se forma...", "opciones": ["Por el arcén.", "Entre los dos carriles.", "Por el carril izquierdo."], "correcta": 1, "explicacion": "Con dos carriles y tráfico detenido en autopista o autovía, el corredor de emergencia se deja en el espacio entre ambos carriles.", "imagen": "img/ambulancia_atasco.jpg", "fallada": true}, {"n": 59, "tema": "Medio ambiente y puntos", "pregunta": "Una moto Euro 4 de gasolina lleva normalmente la etiqueta...", "opciones": ["C.", "ECO.", "B."], "correcta": 0, "explicacion": "Las motos de gasolina Euro 4 y Euro 5 (aproximadamente desde 2016) llevan la etiqueta C verde.", "imagen": "img/etiqueta_c.jpg", "fallada": false}, {"n": 60, "tema": "Normativa 2026", "pregunta": "Los cascos de ciclomotor certificados pueden usarse hasta...", "opciones": ["Indefinidamente.", "El 1 de octubre de 2026.", "El 1 de octubre de 2027."], "correcta": 2, "explicacion": "Solo los ciclomotores tienen periodo transitorio: pueden usar cascos certificados hasta el 1 de octubre de 2027. Las motocicletas, no.", "imagen": "img/scooter.jpg", "fallada": false}, {"n": 61, "tema": "Permisos y documentación", "pregunta": "¿Qué potencia máxima autoriza el permiso A2?", "opciones": ["35 kW.", "25 kW.", "47 kW."], "correcta": 0, "explicacion": "El permiso A2 autoriza motocicletas de hasta 35 kW (unos 47,6 CV).", "imagen": "img/naked_a2.jpg", "fallada": false}, {"n": 62, "tema": "Permisos y documentación", "pregunta": "¿Cuál es la relación potencia/peso máxima de una moto del A2?", "opciones": ["0,2 kW/kg.", "0,3 kW/kg.", "0,1 kW/kg."], "correcta": 0, "explicacion": "La relación potencia/peso de una moto del A2 no puede superar 0,2 kW/kg.", "imagen": "img/trail.jpg", "fallada": false}, {"n": 63, "tema": "Permisos y documentación", "pregunta": "¿Puede conducirse con el A2 una moto de 125 cm³ y 11 kW?", "opciones": ["Solo si se tiene también el permiso B.", "No, solo con el A1.", "Sí."], "correcta": 2, "explicacion": "El A2 incluye la autorización de los permisos AM y A1, así que también permite conducir motos de 125 cm³ y 11 kW.", "imagen": "img/moto125.jpg", "fallada": false}, {"n": 64, "tema": "Permisos y documentación", "pregunta": "Un cuatriciclo de motor de más de 15 kW, ¿puede conducirse con el permiso A1?", "opciones": ["Sí.", "Solo en vías urbanas.", "No."], "correcta": 2, "explicacion": "El A1 solo autoriza triciclos de motor de hasta 15 kW. Un cuatriciclo de más de 15 kW no se puede llevar con A1.", "imagen": "img/triciclo.jpg", "fallada": true}, {"n": 65, "tema": "Permisos y documentación", "pregunta": "Con el permiso B de más de 3 años, ¿se puede conducir una moto de 125 cm³ en Francia?", "opciones": ["No, esa autorización solo vale en España.", "Sí, con un certificado de la autoescuela.", "Sí, en toda la Unión Europea."], "correcta": 0, "explicacion": "La autorización para conducir motos de 125 con el permiso B de más de 3 años solo es válida en territorio español.", "imagen": "img/moto125.jpg", "fallada": true}, {"n": 66, "tema": "Permisos y documentación", "pregunta": "¿Cuál es la velocidad mínima de una motocicleta en autopista o autovía, salvo señalización?", "opciones": ["70 km/h.", "60 km/h.", "50 km/h."], "correcta": 1, "explicacion": "La velocidad mínima en autopista y autovía es la mitad de la genérica: 60 km/h, salvo señalización.", "imagen": "img/R411.jpg", "fallada": false}, {"n": 67, "tema": "Permisos y documentación", "pregunta": "En una vía urbana de plataforma única, la velocidad máxima es...", "opciones": ["30 km/h.", "20 km/h.", "10 km/h."], "correcta": 1, "explicacion": "En las vías urbanas de plataforma única, con calzada y acera al mismo nivel, el límite es 20 km/h.", "imagen": "img/S28.jpg", "fallada": true}, {"n": 68, "tema": "Permisos y documentación", "pregunta": "La tasa máxima de alcohol en aire espirado para un conductor general es...", "opciones": ["0,25 mg/l.", "0,50 mg/l.", "0,15 mg/l."], "correcta": 0, "explicacion": "La tasa general es de 0,25 mg/l en aire espirado (0,5 g/l en sangre).", "imagen": "img/etilometro.jpg", "fallada": false}, {"n": 69, "tema": "Permisos y documentación", "pregunta": "¿Durante cuánto tiempo se aplica la tasa de alcohol reducida de los conductores noveles?", "opciones": ["Los tres primeros años.", "El primer año.", "Los dos primeros años."], "correcta": 2, "explicacion": "Durante los dos primeros años del permiso se aplica la tasa reducida: 0,15 mg/l en aire y 0,3 g/l en sangre.", "imagen": "img/etilometro.jpg", "fallada": false}, {"n": 70, "tema": "Permisos y documentación", "pregunta": "Tras la primera ITV, una motocicleta debe pasarla...", "opciones": ["Cada año.", "Cada 2 años.", "Cada 4 años."], "correcta": 1, "explicacion": "Tras la primera ITV a los 4 años, la moto debe pasarla cada 2 años.", "imagen": "img/elevador.jpg", "fallada": false}, {"n": 71, "tema": "Permisos y documentación", "pregunta": "Una moto con el silenciador averiado que produce ruidos molestos...", "opciones": ["No puede circular en esas condiciones.", "Puede circular solo por vías interurbanas.", "Puede circular si es de día."], "correcta": 0, "explicacion": "Con el silenciador averiado la moto emite ruidos por encima de lo permitido y no puede circular hasta repararlo.", "imagen": "img/partes_moto.jpg", "fallada": true}, {"n": 72, "tema": "Normativa 2026", "pregunta": "¿Debe llevar guantes el pasajero de una moto en una vía interurbana?", "opciones": ["Solo si es menor de edad.", "Sí.", "No, solo el conductor."], "correcta": 1, "explicacion": "Los guantes en vías interurbanas son obligatorios tanto para el conductor como para el pasajero.", "imagen": "img/guantes_verano.jpg", "fallada": true}, {"n": 73, "tema": "Normativa 2026", "pregunta": "¿Qué sanción tiene circular en moto con sandalias?", "opciones": ["Ninguna en ciudad.", "200 € sin pérdida de puntos.", "200 € y 4 puntos."], "correcta": 1, "explicacion": "Circular sin calzado cerrado que cubra todo el pie es infracción grave de 200 €, sin pérdida de puntos.", "imagen": "img/botines.jpg", "fallada": true}, {"n": 74, "tema": "Normativa 2026", "pregunta": "¿Quién queda exento de casco, guantes y calzado cerrado?", "opciones": ["Los conductores de scooter.", "Nadie.", "Ocupantes de vehículos con estructura de autoprotección y cinturones que consten en la tarjeta ITV."], "correcta": 2, "explicacion": "Solo quedan exentos los ocupantes de vehículos con estructura de autoprotección y cinturones que consten en la tarjeta ITV. Deben llevar el cinturón.", "imagen": "img/triciclo.jpg", "fallada": false}, {"n": 75, "tema": "Normativa 2026", "pregunta": "Un repartidor que conduce una moto por trabajo debe llevar chaleco de alta visibilidad...", "opciones": ["Solo de noche.", "Solo en vías interurbanas.", "En todo tipo de vías durante su actividad."], "correcta": 2, "explicacion": "Quien conduce una moto por trabajo, como un repartidor, debe llevar chaleco de alta visibilidad en todo tipo de vías durante su actividad.", "imagen": "img/chalecos.jpg", "fallada": false}, {"n": 76, "tema": "Normativa 2026", "pregunta": "En un tramo de arcén habilitado para motos en atascos, ¿se puede adelantar a otra moto?", "opciones": ["Sí, con precaución.", "No, se circula en fila de uno.", "Sí, si no supera 30 km/h."], "correcta": 1, "explicacion": "En los tramos de arcén habilitados se circula en fila de uno, a 30 km/h como máximo y sin adelantar a otras motos.", "imagen": "img/P31.jpg", "fallada": true}, {"n": 77, "tema": "Normativa 2026", "pregunta": "Para adelantar a un ciclista en una vía con dos carriles por sentido hay que...", "opciones": ["Cambiar completamente de carril.", "Tocar el claxon y mantener el carril.", "Dejar 1,5 m sin salir del carril."], "correcta": 0, "explicacion": "Si la calzada tiene más de un carril por sentido, para adelantar a un usuario vulnerable hay que cambiar completamente de carril.", "imagen": "img/P22.jpg", "fallada": true}, {"n": 78, "tema": "Normativa 2026", "pregunta": "En ciudad, con límite de 50 km/h, al rebasar una grúa que trabaja ocupando el carril, ¿a qué velocidad máxima se debe pasar?", "opciones": ["40 km/h.", "50 km/h.", "30 km/h."], "correcta": 2, "explicacion": "Al rebasar un vehículo inmovilizado que ocupa el carril hay que ir al menos 20 km/h por debajo del límite, también en ciudad: con 50 km/h, como máximo 30.", "imagen": "img/P17.jpg", "fallada": true}, {"n": 79, "tema": "Normativa 2026", "pregunta": "En vía urbana, un vehículo a motor que sigue a una bicicleta en el mismo carril debe mantener al menos...", "opciones": ["2 metros.", "5 metros.", "10 metros."], "correcta": 1, "explicacion": "En ciudad, el vehículo a motor que sigue a una bicicleta o VMP en el mismo carril debe mantener al menos 5 metros.", "imagen": "img/P22.jpg", "fallada": false}, {"n": 80, "tema": "Normativa 2026", "pregunta": "¿Están obligadas las motocicletas a llevar la baliza V-16?", "opciones": ["No.", "Solo en autopistas.", "Sí, desde 2026."], "correcta": 0, "explicacion": "Las motocicletas no están obligadas a llevar la baliza V-16 ni triángulos. Sí deben llevar chaleco reflectante.", "imagen": "img/pata_cabra.jpg", "fallada": true}, {"n": 81, "tema": "Normativa 2026", "pregunta": "En una autovía con tres carriles y tráfico detenido, el corredor de emergencia se deja...", "opciones": ["Entre el carril central y el derecho.", "Entre el carril izquierdo y el central.", "Por el arcén derecho."], "correcta": 1, "explicacion": "Con tres o más carriles, los del carril izquierdo se apartan a la izquierda y el resto a la derecha: el corredor queda entre el izquierdo y el central.", "imagen": "img/ambulancia_atasco.jpg", "fallada": true}, {"n": 82, "tema": "Normativa 2026", "pregunta": "Con nieve que dificulta la circulación en una autopista...", "opciones": ["Se puede adelantar con precaución.", "Se prohíbe adelantar y se circula por el carril derecho.", "Se circula por el carril izquierdo."], "correcta": 1, "explicacion": "Cuando la nieve dificulta la circulación en autopistas y autovías, se prohíbe adelantar y se circula por el carril derecho.", "imagen": "img/P34.jpg", "fallada": false}, {"n": 83, "tema": "Equipamiento", "pregunta": "¿Qué parte del casco absorbe y reparte primero la fuerza de un impacto?", "opciones": ["El acolchado de confort.", "La visera.", "La cobertura exterior o calota."], "correcta": 2, "explicacion": "La calota o cobertura exterior es lo primero que recibe el golpe: absorbe y reparte la fuerza del impacto.", "imagen": "img/casco_integral.jpg", "fallada": true}, {"n": 84, "tema": "Equipamiento", "pregunta": "El revestimiento interior que absorbe la energía no absorbida por la calota suele ser de...", "opciones": ["Fibra de vidrio.", "Policarbonato.", "Poliestireno expandido (EPS)."], "correcta": 2, "explicacion": "El revestimiento interior es de poliestireno expandido (EPS), que absorbe la energía que no ha absorbido la calota.", "imagen": "img/casco_interior.jpg", "fallada": false}, {"n": 85, "tema": "Equipamiento", "pregunta": "¿Qué tipo de casco ofrece mayor protección?", "opciones": ["El jet.", "El modular.", "El integral."], "correcta": 2, "explicacion": "El integral es el casco que más protege, porque cubre también la cara y la mandíbula.", "imagen": "img/casco_integral.jpg", "fallada": false}, {"n": 86, "tema": "Equipamiento", "pregunta": "La visera del casco debe limpiarse...", "opciones": ["Con agua y jabón suave.", "Con alcohol.", "Con disolvente."], "correcta": 0, "explicacion": "La visera se limpia con agua y jabón suave. Disolventes o alcohol pueden dañar el policarbonato y su tratamiento.", "imagen": "img/casco.jpg", "fallada": false}, {"n": 87, "tema": "Equipamiento", "pregunta": "¿Por qué no se debe dejar el casco junto a un radiador o fuente de calor?", "opciones": ["No hay ningún problema.", "Porque se ensucia.", "Porque el calor degrada sus materiales."], "correcta": 2, "explicacion": "El calor excesivo degrada los materiales del casco y reduce su capacidad de protección.", "imagen": "img/casco_jet.jpg", "fallada": false}, {"n": 88, "tema": "Equipamiento", "pregunta": "Pintar o poner adhesivos en un casco de termoplástico...", "opciones": ["Lo refuerza.", "Puede deteriorar el material.", "Es obligatorio para ser visto."], "correcta": 1, "explicacion": "Pinturas, disolventes y adhesivos pueden deteriorar el material de la calota, sobre todo en los cascos de termoplástico.", "imagen": "img/casco_cross.jpg", "fallada": false}, {"n": 89, "tema": "Equipamiento", "pregunta": "En caso de accidente, un casco más ligero...", "opciones": ["Reduce el esfuerzo sobre el cuello.", "No influye.", "Aumenta el esfuerzo en el cuello."], "correcta": 0, "explicacion": "Cuanto más ligero es el casco, menor es el esfuerzo que soporta el cuello en un accidente.", "imagen": "img/casco.jpg", "fallada": false}, {"n": 90, "tema": "Equipamiento", "pregunta": "Una visera tintada o solar...", "opciones": ["Es obligatoria en verano.", "Es la más recomendable de noche.", "No es aconsejable para conducir de noche."], "correcta": 2, "explicacion": "Las viseras tintadas reducen la visión con poca luz: no son aconsejables de noche.", "imagen": "img/casco_integral.jpg", "fallada": false}, {"n": 91, "tema": "Equipamiento", "pregunta": "La principal función de las botas de moto es proteger...", "opciones": ["Los tobillos.", "Las rodillas.", "Las caderas."], "correcta": 0, "explicacion": "La función principal de las botas es proteger los tobillos, una de las zonas más dañadas en las caídas.", "imagen": "img/botas.jpg", "fallada": false}, {"n": 92, "tema": "Equipamiento", "pregunta": "La faja o riñonera protege principalmente...", "opciones": ["La zona lumbar y los riñones.", "El cuello.", "Las manos."], "correcta": 0, "explicacion": "La faja protege la zona lumbar y los riñones y reduce el cansancio en trayectos largos.", "imagen": "img/chaqueta.jpg", "fallada": false}, {"n": 93, "tema": "Equipamiento", "pregunta": "Unos buenos guantes de moto deben...", "opciones": ["Quedar holgados.", "Ajustar bien en la muñeca y no restar sensibilidad.", "Ser lo más gruesos posible aunque resten movilidad."], "correcta": 1, "explicacion": "Los guantes deben ajustar bien en la muñeca y no restar sensibilidad ni movilidad para manejar los mandos con precisión.", "imagen": "img/guantes_nudillos.jpg", "fallada": false}, {"n": 94, "tema": "Equipamiento", "pregunta": "El Gore-tex se utiliza en la ropa de moto por ser...", "opciones": ["Ignífugo.", "Impermeable y transpirable.", "Reflectante."], "correcta": 1, "explicacion": "El Gore-tex se usa porque es impermeable y a la vez transpirable.", "imagen": "img/pantalon.jpg", "fallada": false}, {"n": 95, "tema": "Equipamiento", "pregunta": "La etiqueta de homologación E9 indica que el casco se homologó en...", "opciones": ["Alemania.", "España.", "Italia."], "correcta": 1, "explicacion": "El número tras la E indica el país que homologó el casco: E9 corresponde a España.", "imagen": "img/casco.jpg", "fallada": false}, {"n": 96, "tema": "Equipamiento", "pregunta": "El airbag para motorista, respecto a una espaldera...", "opciones": ["Es menos eficaz.", "Protege una superficie mayor del cuerpo.", "Protege solo la columna."], "correcta": 1, "explicacion": "El airbag protege una superficie mayor (cuello, tórax y espalda) que una espaldera, que solo protege la columna.", "imagen": "img/chaqueta.jpg", "fallada": false}, {"n": 97, "tema": "Equipamiento", "pregunta": "Según los estudios, usar casco reduce la probabilidad de sufrir lesiones en la cabeza...", "opciones": ["Un 10 %.", "A la mitad.", "No la reduce."], "correcta": 1, "explicacion": "Los estudios indican que el casco reduce a la mitad la probabilidad de lesión en la cabeza, y de 3 a 9 veces la de que sea mortal.", "imagen": "img/casco_integral.jpg", "fallada": false}, {"n": 98, "tema": "La motocicleta", "pregunta": "Una moto automática (tipo scooter) transmite el movimiento mediante...", "opciones": ["Caja de cambios de 6 marchas y cadena.", "Cardán y embrague de maneta.", "Variador, correa y embrague centrífugo."], "correcta": 2, "explicacion": "Las automáticas usan variador, correa y embrague centrífugo, que funcionan como los platos, la cadena y los piñones de una bicicleta.", "imagen": "img/scooter.jpg", "fallada": false}, {"n": 99, "tema": "La motocicleta", "pregunta": "Para cambiar de marcha en una moto manual, el orden correcto es...", "opciones": ["Acelerar, engranar y embragar.", "Engranar, embragar, acelerar.", "Embragar, cortar gas, engranar, soltar embrague progresivamente y acelerar."], "correcta": 2, "explicacion": "Primero se embraga, se corta gas, se engrana la marcha con el pie y se suelta el embrague progresivamente mientras se acelera.", "imagen": "img/embrague.jpg", "fallada": false}, {"n": 100, "tema": "La motocicleta", "pregunta": "¿En qué tipo de moto el conductor controla mejor el freno motor?", "opciones": ["En la de transmisión automática.", "En la de cambio manual.", "En las dos por igual."], "correcta": 1, "explicacion": "En la moto de cambio manual el conductor elige la marcha y controla mucho mejor el freno motor. En la automática lo gestiona la transmisión.", "imagen": "img/mandos.jpg", "fallada": false}, {"n": 101, "tema": "La motocicleta", "pregunta": "Una cadena demasiado floja...", "opciones": ["Puede salirse del piñón o la corona.", "No tiene consecuencias.", "Mejora la aceleración."], "correcta": 0, "explicacion": "Una cadena muy floja puede saltar del piñón o la corona, con riesgo de bloqueo de la rueda trasera.", "imagen": "img/cadena.jpg", "fallada": false}, {"n": 102, "tema": "La motocicleta", "pregunta": "Conviene revisar y engrasar la cadena...", "opciones": ["Una vez al año.", "Solo en la ITV.", "Antes de un viaje largo y tras circular con lluvia o polvo."], "correcta": 2, "explicacion": "La cadena se revisa y engrasa antes de un viaje largo y después de circular con lluvia, agua o polvo.", "imagen": "img/cadena.jpg", "fallada": false}, {"n": 103, "tema": "La motocicleta", "pregunta": "¿Cuál es la causa mecánica más relacionada con los accidentes?", "opciones": ["Los frenos.", "Los neumáticos.", "La dirección."], "correcta": 1, "explicacion": "Los neumáticos son la causa mecánica más relacionada con los accidentes, porque son lo único en contacto con el suelo.", "imagen": "img/neumaticos.jpg", "fallada": true}, {"n": 104, "tema": "La motocicleta", "pregunta": "Circular con los neumáticos desinflados...", "opciones": ["Reduce la adherencia y daña su estructura.", "Reduce el consumo.", "Mejora el agarre en curva."], "correcta": 0, "explicacion": "Con poca presión se reduce la adherencia, se calienta el neumático y se puede dañar su estructura interna.", "imagen": "img/neumatico_taller.jpg", "fallada": false}, {"n": 105, "tema": "La motocicleta", "pregunta": "Aunque tengan dibujo, los neumáticos conviene sustituirlos como máximo a los...", "opciones": ["15 años.", "5 años.", "10 años."], "correcta": 1, "explicacion": "Aunque conserven dibujo, la goma envejece: conviene sustituir los neumáticos como máximo a los 5 años.", "imagen": "img/neumaticos.jpg", "fallada": false}, {"n": 106, "tema": "La motocicleta", "pregunta": "Si el nivel del líquido de frenos baja poco a poco con el tiempo, lo normal es que se deba...", "opciones": ["A una fuga grave.", "Al desgaste de las pastillas.", "A un exceso de líquido."], "correcta": 1, "explicacion": "Al desgastarse las pastillas, los pistones avanzan y el nivel baja poco a poco. Es normal y no hay que rellenar sin más.", "imagen": "img/frenos.jpg", "fallada": true}, {"n": 107, "tema": "La motocicleta", "pregunta": "Una bajada repentina del nivel del líquido de frenos indica...", "opciones": ["Una posible fuga en el circuito.", "Que hace frío.", "Desgaste normal."], "correcta": 0, "explicacion": "Si el nivel baja de golpe, probablemente hay una fuga en el circuito: puede comprometer la frenada y hay que revisarlo.", "imagen": "img/frenos.jpg", "fallada": false}, {"n": 108, "tema": "La motocicleta", "pregunta": "En un freno de disco, al apretar la maneta la presión del líquido actúa sobre...", "opciones": ["La cadena.", "Los pistones de la pinza, que aprietan las pastillas contra el disco.", "El cable del freno."], "correcta": 1, "explicacion": "La presión del líquido empuja los pistones de la pinza, que aprietan las pastillas contra el disco y frenan la rueda.", "imagen": "img/frenos.jpg", "fallada": false}, {"n": 109, "tema": "La motocicleta", "pregunta": "Según la mayoría de fabricantes, el aceite de la horquilla conviene cambiarlo aproximadamente...", "opciones": ["Cada 2 años.", "Cada 10 años.", "Nunca."], "correcta": 0, "explicacion": "La horquilla lleva aceite, muelle y válvulas. La mayoría de fabricantes recomiendan cambiar ese aceite cada 2 años o los kilómetros equivalentes.", "imagen": "img/partes_moto.jpg", "fallada": false}, {"n": 110, "tema": "La motocicleta", "pregunta": "Para comprobar el nivel de aceite del motor la moto debe estar...", "opciones": ["En posición vertical.", "Inclinada hacia la derecha.", "Apoyada en la pata de cabra."], "correcta": 0, "explicacion": "Hay que medir el aceite con la moto vertical: una ligera inclinación, como en la pata de cabra, falsea la lectura.", "imagen": "img/cambio_aceite.jpg", "fallada": true}, {"n": 111, "tema": "La motocicleta", "pregunta": "Al llevar pasajero, el haz de luz del faro...", "opciones": ["No cambia.", "Baja.", "Se eleva y puede deslumbrar, por lo que conviene regularlo."], "correcta": 2, "explicacion": "Con pasajero la trasera baja y el faro apunta más alto, por lo que puede deslumbrar. Conviene regular su altura.", "imagen": "img/pasajero.jpg", "fallada": false}, {"n": 112, "tema": "La motocicleta", "pregunta": "Las motos de más de 125 cm³ matriculadas desde 2017 deben llevar...", "opciones": ["ABS.", "Frenada combinada solamente.", "Ningún sistema especial."], "correcta": 0, "explicacion": "Desde enero de 2017, las motos nuevas de más de 125 cm³ o más de 11 kW deben llevar ABS.", "imagen": "img/frenos.jpg", "fallada": false}, {"n": 113, "tema": "La motocicleta", "pregunta": "Una moto nueva de hasta 125 cm³ y 11 kW debe llevar...", "opciones": ["Solo freno de tambor.", "Obligatoriamente doble disco.", "ABS, frenada combinada o ambos."], "correcta": 2, "explicacion": "Las motos nuevas de hasta 125 cm³ y 11 kW deben llevar ABS, frenada combinada o ambos.", "imagen": "img/moto125.jpg", "fallada": true}, {"n": 114, "tema": "Asistentes (ADAS)", "pregunta": "El control de tracción sirve para...", "opciones": ["Aumentar la velocidad máxima.", "Evitar que la rueda trasera patine al acelerar.", "Frenar automáticamente en las curvas."], "correcta": 1, "explicacion": "El control de tracción regula la fuerza del motor para que la rueda trasera no patine al acelerar.", "imagen": "img/curva.jpg", "fallada": false}, {"n": 115, "tema": "Asistentes (ADAS)", "pregunta": "El sistema anti-wheelie evita que...", "opciones": ["La rueda delantera se levante al acelerar.", "Se bloquee la rueda trasera.", "Se cale el motor."], "correcta": 0, "explicacion": "El anti-wheelie o anticaballito evita que la rueda delantera se levante al acelerar.", "imagen": "img/descolgado.jpg", "fallada": false}, {"n": 116, "tema": "Asistentes (ADAS)", "pregunta": "La señal de frenada de emergencia consiste en que, al frenar fuerte...", "opciones": ["Parpadeen los intermitentes para avisar a quien viene detrás.", "Se encienda la luz de carretera.", "Suene el claxon."], "correcta": 0, "explicacion": "En una frenada fuerte parpadean los intermitentes para avisar al vehículo de detrás de que la moto se detiene bruscamente.", "imagen": "img/ruta.jpg", "fallada": false}, {"n": 117, "tema": "Asistentes (ADAS)", "pregunta": "El quickshifter o cambio asistido permite...", "opciones": ["Arrancar sin llave.", "Cambiar de marcha sin accionar el embrague.", "Frenar sin tocar la maneta."], "correcta": 1, "explicacion": "El quickshifter permite subir o bajar marchas sin accionar el embrague.", "imagen": "img/embrague.jpg", "fallada": false}, {"n": 118, "tema": "Asistentes (ADAS)", "pregunta": "La unidad de medición inercial (IMU) mide...", "opciones": ["La presión de los neumáticos.", "La inclinación, el balanceo y las aceleraciones de la moto.", "El nivel de combustible."], "correcta": 1, "explicacion": "La IMU combina acelerómetros y giroscopios para medir inclinación, balanceo y aceleraciones. Muchos asistentes dependen de ella.", "imagen": "img/inclinacion.jpg", "fallada": false}, {"n": 119, "tema": "Asistentes (ADAS)", "pregunta": "El control de frenada en pendiente ayuda a...", "opciones": ["Subir cuestas sin acelerar.", "Aparcar en cuesta.", "Que la rueda trasera no se levante en bajadas pronunciadas."], "correcta": 2, "explicacion": "En bajadas pronunciadas, el control de frenada en pendiente reparte la presión de freno para que la rueda trasera no se levante.", "imagen": "img/P15.jpg", "fallada": false}, {"n": 120, "tema": "Asistentes (ADAS)", "pregunta": "El detector de ángulo muerto avisa de...", "opciones": ["La temperatura del motor.", "Vehículos que hay en la zona no visible por los espejos al cambiar de carril.", "Radares de velocidad."], "correcta": 1, "explicacion": "El detector de ángulo muerto avisa de vehículos que no se ven por los espejos cuando vas a cambiar de carril.", "imagen": "img/vista_superior.jpg", "fallada": false}, {"n": 121, "tema": "Frenada", "pregunta": "Al accionar el freno delantero, la horquilla...", "opciones": ["Se extiende.", "Se comprime.", "No se mueve."], "correcta": 1, "explicacion": "Al frenar con el delantero, el peso se va hacia delante y la horquilla se comprime.", "imagen": "img/frenos.jpg", "fallada": false}, {"n": 122, "tema": "Frenada", "pregunta": "Si en una curva a la derecha se frena con el delantero, la moto tiende a...", "opciones": ["Levantarse y abrirse hacia el carril contrario.", "Mantener la trayectoria.", "Cerrarse hacia el interior."], "correcta": 0, "explicacion": "El freno delantero en curva levanta la moto y abre la trayectoria: en una curva a la derecha te lleva hacia el carril contrario.", "imagen": "img/P13a.jpg", "fallada": true}, {"n": 123, "tema": "Frenada", "pregunta": "Frenar con el trasero en plena curva hace que la moto tienda a...", "opciones": ["Levantarse.", "Abrir la trayectoria.", "Cerrar la trayectoria."], "correcta": 2, "explicacion": "El freno trasero en curva hace que la moto cierre la trayectoria, al contrario que el delantero.", "imagen": "img/P13a.jpg", "fallada": true}, {"n": 124, "tema": "Frenada", "pregunta": "Para no desplazarse hacia el manillar en una frenada fuerte, el conductor debe...", "opciones": ["Apoyar los brazos rígidos.", "Presionar las rodillas contra el depósito.", "Levantarse del asiento."], "correcta": 1, "explicacion": "Presionar las rodillas contra el depósito evita que el cuerpo se vaya hacia delante y cargue el manillar.", "imagen": "img/vista_superior.jpg", "fallada": false}, {"n": 125, "tema": "Frenada", "pregunta": "En una frenada de emergencia, conviene accionar también el embrague para...", "opciones": ["Frenar más con el delantero.", "Cambiar a una marcha más larga.", "Que el motor no empuje la rueda trasera y no se cale."], "correcta": 2, "explicacion": "Embragar en la frenada de emergencia evita que el motor siga empujando la rueda trasera y que la moto se cale.", "imagen": "img/embrague.jpg", "fallada": false}, {"n": 126, "tema": "Frenada", "pregunta": "La forma correcta de empezar a frenar es...", "opciones": ["Solo con el freno motor.", "Con un golpe fuerte de maneta.", "Con una presión inicial suave que aumenta de forma progresiva."], "correcta": 2, "explicacion": "La frenada empieza con presión suave que aumenta de forma progresiva. Un golpe de maneta puede bloquear la rueda.", "imagen": "img/frenos.jpg", "fallada": false}, {"n": 127, "tema": "Frenada", "pregunta": "Si la rueda delantera rebota en un bache mientras se frena...", "opciones": ["Puede dejar de girar y derrapar al volver a tocar el suelo.", "Frena mejor.", "No ocurre nada."], "correcta": 0, "explicacion": "Si la rueda rebota y se separa del suelo con el freno accionado, deja de girar y derrapa al volver a tocar el asfalto.", "imagen": "img/P15a.jpg", "fallada": false}, {"n": 128, "tema": "Frenada", "pregunta": "Si se duplica la velocidad, la distancia de frenado...", "opciones": ["Se multiplica por cuatro.", "Se triplica.", "Se duplica."], "correcta": 0, "explicacion": "La distancia de frenado crece con el cuadrado de la velocidad: al duplicarla, se multiplica por cuatro.", "imagen": "img/R301_120.jpg", "fallada": true}, {"n": 129, "tema": "Curvas", "pregunta": "¿En qué punto de la curva se debe haber terminado de frenar?", "opciones": ["En la salida.", "En el vértice.", "En el punto de entrada, antes de inclinar la moto."], "correcta": 2, "explicacion": "La frenada debe terminar en el punto de entrada, antes de inclinar la moto. Con la moto inclinada, frenar es peligroso.", "imagen": "img/curva.jpg", "fallada": true}, {"n": 130, "tema": "Curvas", "pregunta": "El vértice de la curva es el punto...", "opciones": ["De máxima inclinación y más cercano al interior.", "Donde se empieza a frenar.", "Donde la moto vuelve a estar vertical."], "correcta": 0, "explicacion": "El vértice o ápice es el punto de máxima inclinación y más cercano al interior de la curva.", "imagen": "img/inclinacion.jpg", "fallada": false}, {"n": 131, "tema": "Curvas", "pregunta": "Entre el punto de entrada y el vértice, el acelerador...", "opciones": ["Se mantiene, sin aumentar la aceleración.", "Se cierra del todo.", "Se abre a fondo."], "correcta": 0, "explicacion": "Desde la entrada hasta el vértice se mantiene el gas, sin aumentar la aceleración.", "imagen": "img/curva.jpg", "fallada": false}, {"n": 132, "tema": "Curvas", "pregunta": "A partir del vértice se debe...", "opciones": ["Reducir una marcha.", "Frenar con el delantero.", "Acelerar de forma suave y progresiva."], "correcta": 2, "explicacion": "A partir del vértice se acelera de forma suave y progresiva, lo que ayuda a enderezar la moto.", "imagen": "img/curva.jpg", "fallada": false}, {"n": 133, "tema": "Curvas", "pregunta": "Por debajo de unos 30 km/h, para girar se debe...", "opciones": ["Girar el manillar hacia el lado de la curva.", "Usar el contramanillar.", "Inclinar solo el cuerpo."], "correcta": 0, "explicacion": "Por debajo de unos 30 km/h el giro es directo: se gira el manillar hacia el lado de la curva. El contramanillar es para velocidades mayores.", "imagen": "img/P14a.jpg", "fallada": true}, {"n": 134, "tema": "Curvas", "pregunta": "En una curva, la mirada debe dirigirse...", "opciones": ["A la rueda delantera.", "Al borde exterior.", "Al punto de fuga, lo más lejos posible."], "correcta": 2, "explicacion": "Hay que mirar al punto de fuga, lo más lejos posible. Así se necesitan menos correcciones de trazada, velocidad e inclinación.", "imagen": "img/ruta.jpg", "fallada": false}, {"n": 135, "tema": "Curvas", "pregunta": "Si al acercarte a una curva el punto de fuga no se aleja, la curva...", "opciones": ["Es una recta.", "Se abre.", "Es más cerrada de lo que parecía y hay que reducir."], "correcta": 2, "explicacion": "Si el punto de fuga no se aleja o lo hace despacio al acercarte, la curva es más cerrada de lo que parecía y hay que reducir la velocidad.", "imagen": "img/P13a.jpg", "fallada": true}, {"n": 136, "tema": "Curvas", "pregunta": "El ataque retrasado a una curva cerrada...", "opciones": ["Es más peligroso.", "Da más visibilidad de la salida y suele ser más seguro.", "Está prohibido."], "correcta": 1, "explicacion": "Entrar algo más tarde permite ver antes la salida y salir con más tranquilidad. Es especialmente útil en curvas cerradas y enlazadas.", "imagen": "img/P14a.jpg", "fallada": false}, {"n": 137, "tema": "Curvas", "pregunta": "Empezar a inclinar antes de tiempo en una curva a la derecha suele provocar...", "opciones": ["Salir hacia el arcén derecho.", "Nada.", "Salir hacia el carril contrario."], "correcta": 2, "explicacion": "Si se inclina antes de tiempo en una curva a la derecha, a la salida la moto se va hacia el carril contrario.", "imagen": "img/P13a.jpg", "fallada": true}, {"n": 138, "tema": "Curvas", "pregunta": "En curvas a la izquierda hay que tener especial cuidado porque...", "opciones": ["Los frenos funcionan peor.", "Al inclinar, el cuerpo puede invadir el carril contrario.", "La moto pierde potencia."], "correcta": 1, "explicacion": "En las curvas a la izquierda, al inclinar, la cabeza y el cuerpo pueden invadir el carril contrario aunque las ruedas no lo hagan.", "imagen": "img/curva.jpg", "fallada": false}, {"n": 139, "tema": "Curvas", "pregunta": "Durante la inclinación en curva se debe evitar...", "opciones": ["Mantener el gas constante.", "Cambiar de marcha, frenar con el delantero y cortar gas de golpe.", "Mirar la salida."], "correcta": 1, "explicacion": "Durante la inclinación hay que evitar cualquier maniobra brusca: cambiar de marcha, frenar con el delantero o cortar gas de golpe.", "imagen": "img/inclinacion.jpg", "fallada": false}, {"n": 140, "tema": "Curvas", "pregunta": "Entrar en una curva con una marcha demasiado larga...", "opciones": ["Mejora el agarre.", "Es lo recomendado.", "Da sensación de moto suelta y tentación de frenar."], "correcta": 2, "explicacion": "Con una marcha demasiado larga casi no hay retención, la moto parece suelta y aparece la tentación de frenar en plena curva.", "imagen": "img/curva.jpg", "fallada": false}, {"n": 141, "tema": "Curvas", "pregunta": "En curva, el pie del lado interior conviene...", "opciones": ["Apoyarlo en el suelo.", "Sacarlo de la estribera.", "Retrasarlo y apoyarlo sobre la punta para que no roce."], "correcta": 2, "explicacion": "El pie interior se retrasa y se apoya sobre la punta para que no roce con el suelo al inclinar.", "imagen": "img/descolgado.jpg", "fallada": false}, {"n": 142, "tema": "Curvas", "pregunta": "Si entras en una curva pasado de velocidad, lo primero es intentar...", "opciones": ["Frenar a fondo con el delantero.", "Inclinar algo más la moto mirando la salida.", "Soltar el manillar."], "correcta": 1, "explicacion": "Normalmente queda margen de inclinación: lo primero es inclinar algo más mirando la salida. Frenar fuerte con el delantero te sacaría de la curva.", "imagen": "img/curva.jpg", "fallada": true}, {"n": 143, "tema": "Curvas", "pregunta": "Al acelerar a la salida de la curva, el efecto giroscópico...", "opciones": ["Hace que se incline más.", "No influye.", "Ayuda a enderezar la moto."], "correcta": 2, "explicacion": "Al acelerar aumenta el giro de las ruedas y el efecto giroscópico, que tiende a devolver la moto a la vertical.", "imagen": "img/inclinacion.jpg", "fallada": false}, {"n": 144, "tema": "Pasajero y carga", "pregunta": "El pasajero debe subir a la moto...", "opciones": ["Con la moto en marcha.", "Por el lado de la calzada y cuando quiera.", "Por el lado de la acera y cuando el conductor se lo indique."], "correcta": 2, "explicacion": "El pasajero sube por el lado de la acera y solo cuando el conductor se lo indica y tiene la moto sujeta.", "imagen": "img/pasajero.jpg", "fallada": false}, {"n": 145, "tema": "Pasajero y carga", "pregunta": "Mientras sube el pasajero, el conductor debe tener...", "opciones": ["Los dos pies en el suelo y la moto sujeta.", "Solo el pie derecho en el suelo.", "La moto sobre el caballete."], "correcta": 0, "explicacion": "El conductor debe tener los dos pies en el suelo y la moto bien sujeta mientras sube el pasajero.", "imagen": "img/pasajero.jpg", "fallada": false}, {"n": 146, "tema": "Pasajero y carga", "pregunta": "El pasajero debe sentarse...", "opciones": ["Lo más cerca posible del conductor.", "De lado.", "Lo más atrás posible."], "correcta": 0, "explicacion": "El pasajero se sienta lo más cerca posible del conductor para no desplazar el centro de gravedad.", "imagen": "img/pasajero.jpg", "fallada": false}, {"n": 147, "tema": "Pasajero y carga", "pregunta": "Al bajar de la moto, el pasajero debe tener cuidado con...", "opciones": ["La matrícula.", "El tubo de escape, que puede quemar.", "El faro."], "correcta": 1, "explicacion": "Al bajar hay que tener cuidado con el tubo de escape, que puede causar quemaduras graves.", "imagen": "img/partes_moto.jpg", "fallada": false}, {"n": 148, "tema": "Pasajero y carga", "pregunta": "En una frenada, el pasajero debe...", "opciones": ["Apretar los reposapiés y apoyar las manos en el depósito si es necesario.", "Soltarse.", "Echarse hacia atrás bruscamente."], "correcta": 0, "explicacion": "En la frenada, el pasajero presiona los reposapiés y, si hace falta, apoya las manos en el depósito para no empujar al conductor.", "imagen": "img/pasajero.jpg", "fallada": false}, {"n": 149, "tema": "Pasajero y carga", "pregunta": "¿Dónde es más adecuado llevar los objetos pesados en una moto?", "opciones": ["Lo más bajos y centrados posible.", "Colgados del manillar.", "En un baúl alto."], "correcta": 0, "explicacion": "Los objetos pesados deben ir lo más bajos y centrados posible, cerca del centro de gravedad.", "imagen": "img/maletas.jpg", "fallada": true}, {"n": 150, "tema": "Pasajero y carga", "pregunta": "¿Puede viajar en moto un niño de 6 años?", "opciones": ["Sí, si conduce su padre.", "Sí, con casco.", "No."], "correcta": 2, "explicacion": "Un niño de 6 años no puede viajar en moto. El mínimo excepcional es más de 7 años, con el padre, la madre, el tutor o un adulto autorizado.", "imagen": "img/P21.jpg", "fallada": false}, {"n": 151, "tema": "Pasajero y carga", "pregunta": "¿Puede viajar el pasajero entre el conductor y el manillar?", "opciones": ["Sí, si es un niño.", "No.", "Solo en ciudad."], "correcta": 1, "explicacion": "El pasajero nunca puede ir entre el conductor y el manillar: debe ir detrás, a horcajadas y con los pies en las estriberas.", "imagen": "img/pasajero.jpg", "fallada": false}, {"n": 152, "tema": "Pasajero y carga", "pregunta": "Al preparar un viaje con pasajero y equipaje conviene...", "opciones": ["Ajustar presión de neumáticos y precarga de la suspensión.", "No tocar nada.", "Bajar la presión de los neumáticos."], "correcta": 0, "explicacion": "Con pasajero y equipaje hay que ajustar la presión de los neumáticos y la precarga de la suspensión según el manual.", "imagen": "img/maletas.jpg", "fallada": false}, {"n": 153, "tema": "Conducción preventiva", "pregunta": "Las técnicas de conducción preventiva se basan en...", "opciones": ["Frenos y neumáticos.", "Visión, anticipación y espacio.", "Velocidad y potencia."], "correcta": 1, "explicacion": "La conducción preventiva se basa en tres principios: visión, anticipación y espacio.", "imagen": "img/postura.jpg", "fallada": false}, {"n": 154, "tema": "Conducción preventiva", "pregunta": "En carretera, la distancia de seguridad frontal debe ser al menos de...", "opciones": ["1 segundo.", "3 segundos.", "10 segundos."], "correcta": 1, "explicacion": "En carretera, la distancia de seguridad debe ser al menos de 3 segundos. En zona urbana, 2 segundos.", "imagen": "img/ruta.jpg", "fallada": true}, {"n": 155, "tema": "Conducción preventiva", "pregunta": "En condiciones adversas (lluvia, fatiga...) la distancia de seguridad...", "opciones": ["Se aumenta al menos un segundo más.", "Se mantiene.", "Se reduce."], "correcta": 0, "explicacion": "Con lluvia, fatiga u otras condiciones adversas hay que aumentar la distancia al menos un segundo más.", "imagen": "img/P19.jpg", "fallada": false}, {"n": 156, "tema": "Conducción preventiva", "pregunta": "Si un vehículo te sigue muy pegado, debes...", "opciones": ["Acelerar.", "Frenar de golpe para avisarle.", "Aumentar tu distancia frontal y frenar con suavidad y antelación."], "correcta": 2, "explicacion": "Si te siguen muy pegado, aumenta tu distancia con el de delante para poder frenar con suavidad y antelación. Frenar de golpe provocaría un alcance.", "imagen": "img/ruta.jpg", "fallada": true}, {"n": 157, "tema": "Conducción preventiva", "pregunta": "Al detenerte detrás de otro vehículo, conviene dejar...", "opciones": ["Unos 20 cm.", "Entre 2 y 3 metros.", "10 metros."], "correcta": 1, "explicacion": "Al detenerte detrás de otro vehículo deja 2 o 3 metros: evitas que te arrastre si retrocede y tienes espacio para apartarte.", "imagen": "img/grupo.jpg", "fallada": false}, {"n": 158, "tema": "Conducción preventiva", "pregunta": "La zona junto a otros vehículos donde pueden moverse de repente se llama...", "opciones": ["Zona de frenado.", "Zona de confort.", "Zona de incertidumbre."], "correcta": 2, "explicacion": "Se llama zona de incertidumbre al espacio junto a otros vehículos por el que pueden moverse de repente. Hay que evitar quedarse en ella.", "imagen": "img/ruta.jpg", "fallada": false}, {"n": 159, "tema": "Conducción preventiva", "pregunta": "Los retrovisores deben mirarse...", "opciones": ["Nunca en curva.", "Solo antes de adelantar.", "Con frecuencia, aunque no vayas a maniobrar."], "correcta": 2, "explicacion": "Los retrovisores se miran con frecuencia, aunque no vayas a maniobrar, para saber siempre qué ocurre detrás.", "imagen": "img/mandos.jpg", "fallada": false}, {"n": 160, "tema": "Conducción preventiva", "pregunta": "Para controlar el ángulo muerto de los retrovisores hay que...", "opciones": ["Confiar en los espejos.", "Girar la cabeza.", "Tocar el claxon."], "correcta": 1, "explicacion": "Los espejos tienen un ángulo muerto que solo se controla girando la cabeza antes de cambiar de carril.", "imagen": "img/mandos.jpg", "fallada": false}, {"n": 161, "tema": "Conducción preventiva", "pregunta": "Las manchas de aceite son más frecuentes...", "opciones": ["En autopistas vacías.", "En los puentes.", "En gasolineras y semáforos."], "correcta": 2, "explicacion": "Las manchas de aceite y grasa son más frecuentes en gasolineras y semáforos, donde los coches se detienen.", "imagen": "img/P19.jpg", "fallada": false}, {"n": 162, "tema": "Conducción preventiva", "pregunta": "Ante tapas de alcantarilla en ciudad, lo correcto es...", "opciones": ["Acelerar sobre ellas.", "Frenar encima.", "Elegir con antelación una trayectoria que las evite o pasar con la moto vertical."], "correcta": 2, "explicacion": "Las tapas de alcantarilla pueden estar resbaladizas o mal colocadas: elige con antelación una trayectoria que las evite o pásalas con la moto vertical.", "imagen": "img/P19.jpg", "fallada": false}, {"n": 163, "tema": "Condiciones adversas", "pregunta": "Con viento frontal fuerte conviene...", "opciones": ["Erguirse en la moto.", "Agacharse detrás de la cúpula para reducir la resistencia.", "Soltar el acelerador."], "correcta": 1, "explicacion": "Con viento frontal conviene agacharse tras la cúpula para reducir la resistencia y controlar mejor el gas.", "imagen": "img/postura.jpg", "fallada": false}, {"n": 164, "tema": "Condiciones adversas", "pregunta": "El viento trasero es peligroso porque...", "opciones": ["Reduce la visibilidad.", "Enfría el motor.", "Puede sorprender al frenar y empujar la moto hacia delante."], "correcta": 2, "explicacion": "El viento trasero puede empujar la moto al frenar y provocar un derrape. Hay que reducir velocidad y aumentar la distancia.", "imagen": "img/ruta.jpg", "fallada": false}, {"n": 165, "tema": "Condiciones adversas", "pregunta": "Ante un viento muy fuerte y constante, lo más prudente es...", "opciones": ["Ir más rápido.", "Seguir peleando con él.", "Detenerse un tiempo en un lugar seguro."], "correcta": 2, "explicacion": "Pelear con un viento muy fuerte agota y acaba siendo peligroso: lo prudente es detenerse un tiempo en un lugar seguro.", "imagen": "img/P29.jpg", "fallada": false}, {"n": 166, "tema": "Condiciones adversas", "pregunta": "Si no se puede evitar circular con nieve, lo adecuado es...", "opciones": ["Ir rápido para no caerse.", "Velocidad muy reducida y aprovechar las rodadas de otros vehículos.", "Circular por el centro sin marcas."], "correcta": 1, "explicacion": "Con nieve, velocidad muy reducida y aprovechar las rodadas de otros vehículos, donde suele haber menos nieve y hielo.", "imagen": "img/P34.jpg", "fallada": false}, {"n": 167, "tema": "Condiciones adversas", "pregunta": "Con niebla en moto se deben usar...", "opciones": ["Las luces cortas y guiarse por las líneas de la derecha.", "Ninguna luz.", "Las luces largas."], "correcta": 0, "explicacion": "Con niebla se usan las luces cortas, porque las largas reflejan en la niebla y empeoran la visión, y uno se guía por las líneas de la derecha.", "imagen": "img/P33.jpg", "fallada": true}, {"n": 168, "tema": "Condiciones adversas", "pregunta": "Con lluvia, para retirar el agua de la visera, es preferible...", "opciones": ["Abrirla del todo.", "Limpiarla con el guante.", "Girar ligeramente la cabeza a un lado y a otro."], "correcta": 2, "explicacion": "Limpiar la visera con el guante suele empeorar la visión. Girar un poco la cabeza a cada lado deja que el aire retire el agua.", "imagen": "img/casco_integral.jpg", "fallada": false}, {"n": 169, "tema": "Condiciones adversas", "pregunta": "Para evitar que la visera se empañe se puede...", "opciones": ["Llevarla ligeramente abierta para que circule el aire.", "Cerrarla del todo.", "Respirar por la nariz."], "correcta": 0, "explicacion": "Llevar la visera ligeramente abierta hace circular el aire y evita que se empañe.", "imagen": "img/casco_interior.jpg", "fallada": false}, {"n": 170, "tema": "Condiciones adversas", "pregunta": "Con viento racheado, el conductor debe...", "opciones": ["Circular muy pegado al arcén.", "Agarrar el manillar con rigidez.", "Ir relajado y preparado para reacciones repentinas de la moto."], "correcta": 2, "explicacion": "Con viento racheado hay que ir relajado y preparado para reacciones repentinas de la moto. Agarrar el manillar con rigidez empeora el control.", "imagen": "img/P29.jpg", "fallada": false}, {"n": 171, "tema": "Factor humano", "pregunta": "La alcoholemia alcanza su máximo entre...", "opciones": ["6 y 8 horas después de beber.", "5 y 10 minutos después de beber.", "30 y 90 minutos después de beber."], "correcta": 2, "explicacion": "El alcohol se detecta en sangre a los 5 minutos, pero el máximo se alcanza entre 30 y 90 minutos después de beber.", "imagen": "img/etilometro.jpg", "fallada": true}, {"n": 172, "tema": "Factor humano", "pregunta": "El factor que más influye en la tasa de alcohol es...", "opciones": ["La cantidad de alcohol ingerido.", "La hora del día.", "El tipo de vaso."], "correcta": 0, "explicacion": "El factor que más influye en la tasa es la cantidad de alcohol ingerido.", "imagen": "img/etilometro.jpg", "fallada": false}, {"n": 173, "tema": "Factor humano", "pregunta": "Las bebidas gaseosas o calientes hacen que el alcohol...", "opciones": ["Se elimine antes.", "No haga efecto.", "Se absorba más rápido."], "correcta": 2, "explicacion": "Las bebidas gaseosas o calientes aceleran la absorción del alcohol.", "imagen": "img/etilometro.jpg", "fallada": false}, {"n": 174, "tema": "Factor humano", "pregunta": "Durante las horas de sueño el alcohol se elimina...", "opciones": ["Igual.", "Más deprisa.", "Más lentamente."], "correcta": 2, "explicacion": "Durante el sueño el organismo elimina el alcohol más lentamente.", "imagen": "img/etilometro.jpg", "fallada": true}, {"n": 175, "tema": "Factor humano", "pregunta": "El 'efecto túnel' consiste en...", "opciones": ["Una reducción del campo visual.", "Ver mejor de noche.", "Oír peor dentro del casco."], "correcta": 0, "explicacion": "El efecto túnel es la reducción del campo visual que provocan la velocidad o el alcohol: se ve menos por los lados.", "imagen": "img/R301_120.jpg", "fallada": false}, {"n": 176, "tema": "Factor humano", "pregunta": "Un choque a 50 km/h equivale aproximadamente a caer desde...", "opciones": ["Un tercer piso.", "Un décimo piso.", "Un primer piso."], "correcta": 0, "explicacion": "Un choque a 50 km/h acumula una energía equivalente a caer desde un tercer piso.", "imagen": "img/R301_90.jpg", "fallada": false}, {"n": 177, "tema": "Factor humano", "pregunta": "Las horas con más riesgo de somnolencia son...", "opciones": ["De 12 a 13.", "De 9 a 11 y de 18 a 20.", "De 3 a 5 de la madrugada y de 14 a 16."], "correcta": 2, "explicacion": "Las horas de mayor riesgo de somnolencia son de 3 a 5 de la madrugada y de 14 a 16, después de comer.", "imagen": "img/postura.jpg", "fallada": true}, {"n": 178, "tema": "Factor humano", "pregunta": "Los estimulantes como el café, contra el sueño...", "opciones": ["Lo eliminan.", "Pueden provocar un efecto rebote con sueño repentino.", "No tienen ningún efecto."], "correcta": 1, "explicacion": "El café solo retrasa el sueño y puede provocar un efecto rebote, con sueño repentino. El único remedio real es dormir.", "imagen": "img/postura.jpg", "fallada": false}, {"n": 179, "tema": "Factor humano", "pregunta": "Algunos antihistamínicos para la alergia pueden producir...", "opciones": ["Somnolencia.", "Más agudeza visual.", "Mejora de los reflejos."], "correcta": 0, "explicacion": "Algunos antihistamínicos producen somnolencia. Nunca se deben mezclar con alcohol.", "imagen": "img/botiquin.jpg", "fallada": false}, {"n": 180, "tema": "Factor humano", "pregunta": "El estrés al conducir...", "opciones": ["No influye.", "Aumenta la agresividad y la tendencia a incumplir normas.", "Mejora la atención."], "correcta": 1, "explicacion": "El estrés aumenta la agresividad, la hostilidad y la tendencia a incumplir normas, y hace las decisiones más lentas.", "imagen": "img/postura.jpg", "fallada": false}, {"n": 181, "tema": "Factor humano", "pregunta": "Mezclar drogas y alcohol...", "opciones": ["Anula sus efectos.", "Potencia sus efectos de forma imprevisible.", "Es legal en pequeñas dosis."], "correcta": 1, "explicacion": "Mezclar drogas y alcohol potencia sus efectos de forma imprevisible y muy peligrosa.", "imagen": "img/postura.jpg", "fallada": false}, {"n": 182, "tema": "Factor humano", "pregunta": "¿Qué tres mecanismos usamos para responder al tráfico?", "opciones": ["Velocidad, frenos y luces.", "Oído, olfato y tacto.", "Percepción, atención y capacidades motoras."], "correcta": 2, "explicacion": "Respondemos al tráfico con tres mecanismos: percepción (captar la información), atención (seleccionar lo importante) y capacidades motoras (ejecutar).", "imagen": "img/postura.jpg", "fallada": false}, {"n": 183, "tema": "Factor humano", "pregunta": "Al empezar un tratamiento con un medicamento nuevo conviene...", "opciones": ["Tomar café.", "Conducir como siempre.", "Evitar conducir o ser muy prudente hasta conocer sus efectos."], "correcta": 2, "explicacion": "Al empezar un tratamiento hay que evitar conducir o ser muy prudente hasta conocer cómo te afecta, y consultar al médico.", "imagen": "img/botiquin.jpg", "fallada": false}, {"n": 184, "tema": "Accidentes", "pregunta": "¿Qué lesiones son las más frecuentes en los motoristas accidentados?", "opciones": ["Las de las extremidades, sobre todo las inferiores.", "Las de los oídos.", "Las de las manos exclusivamente."], "correcta": 0, "explicacion": "Las lesiones más frecuentes en motoristas son las de las extremidades, sobre todo las inferiores.", "imagen": "img/ambulancia.jpg", "fallada": false}, {"n": 185, "tema": "Accidentes", "pregunta": "La caída en la que la rueda trasera pierde adherencia, la recupera de golpe y lanza al conductor por encima se llama...", "opciones": ["Lowside.", "Caballito.", "Highside."], "correcta": 2, "explicacion": "El highside ocurre cuando la rueda trasera pierde adherencia y la recupera de golpe, lanzando al conductor por encima de la moto.", "imagen": "img/descolgado.jpg", "fallada": false}, {"n": 186, "tema": "Accidentes", "pregunta": "Un extintor se debe dirigir...", "opciones": ["Al humo.", "A las llamas más altas.", "A la base del fuego."], "correcta": 2, "explicacion": "El extintor se dirige a la base del fuego, donde está el material que arde.", "imagen": "img/ambulancia.jpg", "fallada": false}, {"n": 187, "tema": "Accidentes", "pregunta": "Si un vehículo arde y no hay extintor, se puede usar...", "opciones": ["Agua.", "Mantas, tierra o arena.", "Gasolina."], "correcta": 1, "explicacion": "Sin extintor se pueden usar mantas, tierra o arena. Nunca agua en un vehículo, porque puede extender el fuego del combustible.", "imagen": "img/botiquin.jpg", "fallada": false}, {"n": 188, "tema": "Accidentes", "pregunta": "¿Cuándo se puede mover a un herido?", "opciones": ["Solo ante peligro de incendio o atropello, o para hacer RCP o colocarlo en posición lateral de seguridad.", "Para llevarlo a un hospital en tu moto.", "Siempre que esté consciente."], "correcta": 0, "explicacion": "Solo se mueve a un herido ante peligro de incendio o atropello, o para hacer RCP o colocarlo en posición lateral de seguridad.", "imagen": "img/rcp.jpg", "fallada": false}, {"n": 189, "tema": "Accidentes", "pregunta": "¿Se puede llamar al 112 desde un móvil sin cobertura de tu compañía?", "opciones": ["Solo con saldo.", "No.", "Sí, y es gratuito."], "correcta": 2, "explicacion": "El 112 es gratuito y se puede llamar aunque tu móvil no tenga cobertura de tu compañía.", "imagen": "img/ambulancia.jpg", "fallada": false}, {"n": 190, "tema": "Accidentes", "pregunta": "A un herido consciente que pide agua...", "opciones": ["Se le da agua con azúcar.", "No se le da de beber como norma general.", "Se le da alcohol para el dolor."], "correcta": 1, "explicacion": "Como norma general no se da de beber a un herido: podría necesitar una intervención o atragantarse.", "imagen": "img/botiquin.jpg", "fallada": false}, {"n": 191, "tema": "Accidentes", "pregunta": "Para ayudar a respirar a un herido sin casco se pueden...", "opciones": ["Dar golpes en la espalda.", "Levantar las piernas siempre.", "Aflojar las prendas que opriman el cuello."], "correcta": 2, "explicacion": "A un herido se le aflojan las prendas que opriman el cuello para facilitar la respiración.", "imagen": "img/botiquin.jpg", "fallada": false}, {"n": 192, "tema": "Señales", "pregunta": "Las señales triangulares con borde rojo indican...", "opciones": ["Información.", "Obligación.", "Peligro."], "correcta": 2, "explicacion": "Las señales triangulares con borde rojo advierten de un peligro.", "imagen": "img/P13a.jpg", "fallada": false}, {"n": 193, "tema": "Señales", "pregunta": "La señal circular con una motocicleta negra y borde rojo indica...", "opciones": ["Entrada prohibida a motocicletas.", "Vía reservada a motocicletas.", "Aparcamiento de motos."], "correcta": 0, "explicacion": "La señal circular con borde rojo y una motocicleta negra prohíbe la entrada a motocicletas.", "imagen": "img/R104.jpg", "fallada": false}, {"n": 194, "tema": "Señales", "pregunta": "La señal triangular con una manga de viento advierte de...", "opciones": ["Viento transversal.", "Zona de obras.", "Aeropuerto cercano."], "correcta": 0, "explicacion": "La señal triangular con una manga de viento advierte de viento transversal.", "imagen": "img/P29.jpg", "fallada": false}, {"n": 195, "tema": "Señales", "pregunta": "La señal que obliga a encender el alumbrado de corto alcance es...", "opciones": ["Cuadrada azul.", "Circular azul con un faro.", "Triangular con un faro."], "correcta": 1, "explicacion": "La señal circular azul con un faro obliga a encender el alumbrado de corto alcance (luz de cruce).", "imagen": "img/R413.jpg", "fallada": false}, {"n": 196, "tema": "Señales", "pregunta": "Si un agente indica algo contrario a un semáforo, se obedece...", "opciones": ["Al semáforo.", "Al agente.", "A la señal vertical."], "correcta": 1, "explicacion": "Las indicaciones de los agentes prevalecen sobre semáforos, señales y normas.", "imagen": "img/P3.jpg", "fallada": false}, {"n": 197, "tema": "Medio ambiente y puntos", "pregunta": "¿Qué etiqueta ambiental lleva una moto eléctrica?", "opciones": ["CERO.", "C.", "ECO."], "correcta": 0, "explicacion": "Las motos eléctricas llevan la etiqueta CERO azul.", "imagen": "img/etiqueta_cero.jpg", "fallada": false}, {"n": 198, "tema": "Medio ambiente y puntos", "pregunta": "Una moto de gasolina Euro 3 lleva la etiqueta...", "opciones": ["Ninguna.", "B.", "C."], "correcta": 1, "explicacion": "Las motos de gasolina Euro 3 (aproximadamente 2007-2016) llevan la etiqueta B amarilla.", "imagen": "img/etiqueta_b.jpg", "fallada": false}, {"n": 199, "tema": "Medio ambiente y puntos", "pregunta": "¿Con cuántos puntos empieza un conductor que obtiene su primer permiso?", "opciones": ["12.", "8.", "15."], "correcta": 1, "explicacion": "Un conductor con su primer permiso empieza con 8 puntos. Al resto se le asignan 12.", "imagen": "img/postura.jpg", "fallada": false}, {"n": 200, "tema": "Medio ambiente y puntos", "pregunta": "Conducir con una tasa superior a 0,50 mg/l en aire supone...", "opciones": ["6 puntos.", "2 puntos.", "4 puntos."], "correcta": 0, "explicacion": "Conducir con más de 0,50 mg/l de alcohol en aire supone 6 puntos. Entre 0,25 y 0,50 son 4 puntos (conductor general).", "imagen": "img/etilometro.jpg", "fallada": false}];